with enriched as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, sum(monthly_fee) over (partition by plan) as plan_sum_monthly_fee, first_value(monthly_fee, true) over (partition by status order by start_date, id rows between unbounded preceding and current row) as first_known_monthly_fee from subscriptions) select id, customer_id, plan, start_date, end_date, monthly_fee, status, first_known_monthly_fee, case when status rlike '^(PAUSED|ACTIVE)$' then 'OTHER_ZONE' when status rlike '^(CANCELLED|EXPIRED)$' then 'CORE' else 'GROUP_A' end as status_zone from enriched;
